const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox','--disable-dev-shm-usage']});
 const page=await browser.newPage({viewport:{width:1280,height:900},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://localhost:3002');
 await page.locator('[data-class="knight"]').click();
 await page.locator('#begin-button').click();
 await page.locator('[data-action="attack"]').click();
 await page.waitForTimeout(600);
 await page.screenshot({path:'/tmp/opencode/ashenoath.jpg',type:'jpeg',quality:78});
 const info=await page.evaluate(()=>({title:document.querySelector('#screen-title').innerText,hero:document.querySelector('#hero-hp-text').innerText,enemy:document.querySelector('#enemy-hp-text').innerText,intent:document.querySelector('#intent-title').innerText,actions:[...document.querySelectorAll('.action-button')].map(x=>[x.innerText,x.disabled])}));
 console.log(JSON.stringify({info,errors},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
